    }

    // دالة حجب أرقام البطاقة القياسية
    fun maskPan(rawPan: String): String {
        return if (rawPan.length >= 10) {
            "${rawPan.take(6)}${"*".repeat(rawPan.length - 10)}${rawPan.takeLast(4)}"
        } else {
            "**********"
        }
    }
